import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, html

from src.components import build_photo_cards
from src.sidecar.database import FeaturesDatabase


def _get_db(folder):
    """Get a FeaturesDatabase for folder, or None if no DB exists."""
    db_path = FeaturesDatabase.default_db_path(folder)
    if not db_path.exists():
        return None
    return FeaturesDatabase(db_path)


def register_search_callback(app):
    @app.callback(
        Output("search-results", "children"),
        Output("search-status", "children"),
        Output("photo-list-store", "data", allow_duplicate=True),
        Input("btn-search", "n_clicks"),
        State("search-input", "value"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def run_search(btn_search, query, folder):
