                build_photo_cards(results, folder=folder, source="search"),
                dbc.Alert(f"{len(results)} result(s) found.", color="success", dismissable=True),
                {"paths": [r.get("image_path", "") for r in results], "index": None},
            )
        finally:
            db.close()

